import java.util.*;
import java.io.*;

public class Main {
    static char[][] gridA = new char[15][15];
    static char[][] gridB = new char[15][15];
    static int[][] delta = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    static int[][][] nodeIndex = new int[65][15][15];
    static int[][] maxFlowCap = new int[15][15];
    static int nodeCounter = 1;

    static class Edge {
        int start, end;
        long capacity, flow;

        public Edge() {}

        public Edge(int u, int v, long cap) {
            this.start = u;
            this.end = v;
            this.capacity = cap;
            this.flow = 0;
        }
    }

    static class DinicFlow {
        int totalNodes;
        List<Edge> edges;
        List<List<Integer>> adj;
        int[] level, ptr;

        public DinicFlow(int N) {
            this.totalNodes = N;
            edges = new ArrayList<>();
            adj = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                adj.add(new ArrayList<>());
            }
            level = new int[N];
            ptr = new int[N];
        }

        void addEdge(int u, int v, long cap) {
            if (u != v) {
                edges.add(new Edge(u, v, cap));
                adj.get(u).add(edges.size() - 1);
                edges.add(new Edge(v, u, 0));
                adj.get(v).add(edges.size() - 1);
            }
        }

        boolean buildLevelGraph(int S, int T) {
            Arrays.fill(level, totalNodes + 1);
            Queue<Integer> q = new LinkedList<>();
            q.offer(S);
            level[S] = 0;
            while (!q.isEmpty()) {
                int u = q.poll();
                if (u == T) break;
                for (int e_idx : adj.get(u)) {
                    Edge e = edges.get(e_idx);
                    if (e.flow < e.capacity && level[e.end] > level[e.start] + 1) {
                        level[e.end] = level[e.start] + 1;
                        q.offer(e.end);
                    }
                }
            }
            return level[T] != totalNodes + 1;
        }

        long sendFlow(int u, int T, long flow) {
            if (u == T || flow == 0) return flow;
            for (; ptr[u] < adj.get(u).size(); ++ptr[u]) {
                int e_idx = adj.get(u).get(ptr[u]);
                Edge e = edges.get(e_idx);
                Edge oe = edges.get(e_idx ^ 1);
                if (level[e.end] == level[e.start] + 1) {
                    long amt = e.capacity - e.flow;
                    if (flow != -1 && amt > flow) amt = flow;
                    long pushed = sendFlow(e.end, T, amt);
                    if (pushed > 0) {
                        e.flow += pushed;
                        oe.flow -= pushed;
                        return pushed;
                    }
                }
            }
            return 0;
        }

        long maxFlow(int S, int T) {
            long totalFlow = 0;
            while (buildLevelGraph(S, T)) {
                Arrays.fill(ptr, 0);
                long flow;
                while ((flow = sendFlow(S, T, -1)) > 0) {
                    totalFlow += flow;
                }
            }
            return totalFlow;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                gridA[i][j] = line.charAt(j - 1);
            }
        }

        for (int i = 0; i <= t + 1; i++) {
            for (int j = 1; j <= n; j++) {
                String line = br.readLine();
                for (int k = 1; k <= n; k++) {
                    gridB[j][k] = line.charAt(k - 1);
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                nodeIndex[0][i][j] = nodeCounter++;
            }
        }
        nodeCounter++;
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                gridB[i][j] = line.charAt(j - 1);
            }
        }

        int[][] maxFlowCap = new int[15][15];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                maxFlowCap[i][j] = -1;
            }
        }

        Queue<int[]> q = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (gridA[i][j] == 'Z') {
                    q.offer(new int[]{i, j});
                    maxFlowCap[i][j] = 0;
                }
            }
        }

        while (!q.isEmpty()) {
            int[] pos = q.poll();
            int y = pos[0], x = pos[1];
            for (int i = 0; i < 4; i++) {
                int ny = y + delta[i][0], nx = x + delta[i][1];
                if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && gridA[ny][nx] != 'Y' && maxFlowCap[ny][nx] == -1) {
                    maxFlowCap[ny][nx] = maxFlowCap[y][x] + 1;
                    q.offer(new int[]{ny, nx});
                }
            }
        }

        int INF = (int)1e9;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (maxFlowCap[i][j] == -1 || maxFlowCap[i][j] > t) {
                    maxFlowCap[i][j] = INF;
                }
            }
        }

        int s = 0;
        int t_node = nodeCounter - 1;
        DinicFlow network = new DinicFlow(nodeCounter);

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (gridA[i][j] >= '1' && gridA[i][j] <= '9') {
                    network.addEdge(s, nodeIndex[0][i][j], gridA[i][j] - '0');
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (gridA[i][j] == 'Y' || gridA[i][j] == 'Z') continue;
                for (int k = 0; k < 4; k++) {
                    int ny = i + delta[k][0], nx = j + delta[k][1];
                    if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && gridA[ny][nx] != 'Y' && gridA[ny][nx] != 'Z') {
                        for (int x = 0; x < t; x++) {
                            if (maxFlowCap[ny][nx] >= x + 1 && maxFlowCap[i][j] > x) {
                                network.addEdge(nodeIndex[x][i][j], nodeIndex[x + 1][ny][nx], 1000);
                            }
                        }
                    }
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (gridA[i][j] == 'Y' || gridA[i][j] == 'Z') continue;
                for (int x = 0; x <= t; x++) {
                    if (gridB[i][j] >= '1' && gridB[i][j] <= '9') {
                        network.addEdge(nodeIndex[x][i][j], nodeIndex[t + 1][i][j], gridB[i][j] - '0');
                    }
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (gridA[i][j] == 'Y' || gridA[i][j] == 'Z') continue;
                if (gridB[i][j] >= '1' && gridB[i][j] <= '9') {
                    network.addEdge(nodeIndex[t + 1][i][j], t_node, gridB[i][j] - '0');
                }
            }
        }

        System.out.println(network.maxFlow(s, t_node));
    }
}
